import{_ as t,o as s,c as a,a5 as i}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Debug Tool: Object Lifecycle Stress","description":"","frontmatter":{},"headers":[],"relativePath":"sections/debug_tools/object_lifecycle_stress.md","filePath":"sections/debug_tools/object_lifecycle_stress.md"}'),o={name:"sections/debug_tools/object_lifecycle_stress.md"};function l(c,e,r,n,d,h){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="debug-tool-object-lifecycle-stress" tabindex="-1">Debug Tool: Object Lifecycle Stress <a class="header-anchor" href="#debug-tool-object-lifecycle-stress" aria-label="Permalink to &quot;Debug Tool: Object Lifecycle Stress&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Stress-tests the object lifecycle by creating many primitives, simulating briefly, and then removing them, in an endless loop. This manual diagnostic tool runs headless and can be used to inspect memory handling over time.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>object_lifecycle_stress</code>. Source: <code>examples/tools/debug/object_lifecycle_stress.cpp</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Build with <code>RAISIM_DEBUG_TOOLS=ON</code> as described in <a href="./../DebugTools.html">Regression and Debug Tools</a>, then run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-debug/examples/object_lifecycle_stress</span></span></code></pre></div><p>On Windows, run <code>build-debug\\bin\\object_lifecycle_stress.exe</code> instead. The tool runs until you stop it with Ctrl+C.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Each iteration creates a 6 × 6 × 6 grid of boxes, spheres, capsules, and cylinders, integrates five steps, and removes them again.</li><li>Intended as a stress test for object lifecycle and memory handling.</li></ul>',11)])])}const p=t(o,[["render",l]]);export{u as __pageData,p as default};
